import React from "react";

function MsgHistory({obj}) {
  const headers = ["Date", "Message"];
  return (
    <table className=" flex  ">
      <thead>
        <tr>
          {headers.map((h) => {
            return <td>{h}</td>;
          })}
        </tr>
      </thead>
      <tbody>
        {
          obj.map((o)=>{
            return(
              <tr>
                <td>{o.date}</td>
                <td>{o.msg}</td>
              </tr>
            )
          })
        }
      </tbody>
    </table>
  );
}

export default MsgHistory;
